import pygame
class Maze:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.walls = []

    def add_wall(self, x, y):
        self.walls.append((x, y)

    def draw(self, screen):
        for x, y in self.walls:
            pygame.draw.rect(screen, (0, 0, 0), (x, y, 50, 50))
